import type { FastifyInstance, FastifyRequest, FastifyReply } from "fastify";
import prisma from "../lib/prisma.js";
import bcrypt from "bcryptjs";
import jwt from "jsonwebtoken";

const JWT_SECRET = process.env.JWT_SECRET ?? "your-secret-key";

// Hurl 스펙 에러 포맷: {"errors": {"field": ["message"]}}
function fieldError(field: string, message: string) {
  return { errors: { [field]: [message] } };
}

export async function authRoutes(app: FastifyInstance): Promise<void> {
  // 회원가입
  app.post("/api/users", async (request: FastifyRequest, reply: FastifyReply) => {
    const { user } = request.body as { user?: { username?: string; email?: string; password?: string } };
    const { username, email, password } = user || {};

    // 필수 필드 검증 (빈 문자열까지 철저히 체크)
    if (!username || username.trim() === "") {
      return reply.code(422).send(fieldError("username", "can't be blank"));
    }
    if (!email || email.trim() === "") {
      return reply.code(422).send(fieldError("email", "can't be blank"));
    }
    if (!password || password.trim() === "") {
      return reply.code(422).send(fieldError("password", "can't be blank"));
    }

    // 중복 체크 (username, email 개별 체크로 Hurl 스펙 맞춤)
    const existingByEmail = await prisma.user.findUnique({ where: { email } });
    if (existingByEmail) {
      return reply.code(409).send(fieldError("email", "has already been taken"));
    }
    const existingByUsername = await prisma.user.findUnique({ where: { username } });
    if (existingByUsername) {
      return reply.code(409).send(fieldError("username", "has already been taken"));
    }

    const hashedPassword = await bcrypt.hash(password, 10);
    const created = await prisma.user.create({
      data: {
        username,
        email,
        password: hashedPassword,
        bio: null,
        image: null,
      },
    });

    const token = jwt.sign({ id: created.id, username, email }, JWT_SECRET, { expiresIn: "7d" });

    return reply.code(201).send({
      user: {
        username: created.username,
        email: created.email,
        bio: created.bio ?? null,
        image: created.image ?? null,
        token,
      },
    });
  });

  // 로그인
  app.post("/api/users/login", async (request: FastifyRequest, reply: FastifyReply) => {
    const { user } = request.body as { user?: { email?: string; password?: string } };
    const { email, password } = user || {};

    // 필수 필드 검증
    if (!email || email.trim() === "") {
      return reply.code(422).send(fieldError("email", "can't be blank"));
    }
    if (!password || password.trim() === "") {
      return reply.code(422).send(fieldError("password", "can't be blank"));
    }

    const found = await prisma.user.findUnique({ where: { email } });
    if (!found) {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    const isValid = await bcrypt.compare(password, found.password);
    if (!isValid) {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }

    const token = jwt.sign({ id: found.id, username: found.username, email: found.email }, JWT_SECRET, { expiresIn: "7d" });

    return {
      user: {
        username: found.username,
        email: found.email,
        bio: found.bio ?? null,
        image: found.image ?? null,
        token,
      },
    };
  });
}

