  app.get("/api/user", async (request: AuthRequest, reply: FastifyReply) => {
    const authHeader = (request.headers as any).authorization as string | undefined;
    if (!authHeader) {
      console.error("GET /api/user: No auth header");
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }
    const match = authHeader.match(/^Token\s+(.+)$/i);
    if (!match) {
      console.error("GET /api/user: No token match");
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }
    let decoded: { id: string; username?: string; email?: string };
    try {
      decoded = jwt.verify(match[1], JWT_SECRET) as any;
    } catch (err) {
      console.error("GET /api/user: JWT verify failed", err);
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }
    console.error("GET /api/user: Decoded", decoded);
    request.user = { id: decoded.id, username: decoded.username ?? "", email: decoded.email ?? "" };

    const user = await prisma.user.findUnique({
      where: { id: request.user!.id },
      select: { id: true, username: true, email: true, bio: true, image: true },
    });
    console.error("GET /api/user: DB user", user);

    if (!user) {
      console.error("GET /api/user: User not found");
      return reply.code(404).send({ errors: [{ message: "User not found" }] });
    }

    const newToken = jwt.sign({ id: user.id, username: user.username, email: user.email }, JWT_SECRET, { expiresIn: "30d" });
    console.error("GET /api/user: New token generated");

    reply.send({
      user: {
        username: user.username,
        email: user.email,
        bio: user.bio ?? null,
        image: user.image ?? null,
        token: newToken,
      },
    });
