      decoded = jwt.verify(match[1], JWT_SECRET) as any;
    } catch {
      return reply.code(401).send({ errors: { credentials: ["invalid"] } });
    }
    request.user = { id: decoded.id, username: decoded.username ?? "", email: decoded.email ?? "" };

    const userId = request.user!.id; // GET과 동일하게 수정 시도했었음
    ...
```
이 코드에서 `jwt`가 전역 스코프의 `import jwt from "jsonwebtoken"`와 `const jwt = await import(...)`로 혼용되어 불일치가 발생할 수 있습니다. 전역 `jwt`는 이미 import되어 있지만, `await import`로 가져온 `jwt` 모듈과 전역 `jwt` 변수가 같은지 불확실합니다. 하지만 지금 로그에는 PUT 요청 자체의 디버그 로그가 아예 안 찍혔습니다. 디버그 로그가 찍히려면 `try { const authHeader = ... console.log(...) } catch...` 블록 안으로 들어가야 하는데, 아예 찍히지 않았다는 것은 PUT 요청 라우팅 자체가 `app.put("/api/user", ...)` 핸들러로 연결되지 않았다는 뜻입니다.

Fastify에서 PUT 요청이 들어왔을 때 라우트가 없으면 404를 반환해야 하는데 401을 반환했다는 것은, `app.authenticate` 같은 preHandler가 global하게 적용되어 있거나, 다른 곳에서 `app.put("/api/user", { preHandler: ... })`를 등록했을 가능성이 있습니다. 하지만 `authPlugin`은 `decorate`만 하고 preHandler를 걸지 않습니다. `user.ts`에서는 preHandler를 제거했었습니다.

그렇다면 PUT 요청이 `/api/user`가 아닌 다른 URL로 가고 있을 가능성은 없고, Authorization 헤더가 아예 없거나 제대로 전달되지 않아 401이 난다고 생각할 수 있지만, Hurl 테스트에서는 Authorization 헤더를 `Token {{token}}` 형식으로 보내고 있고, GET에서는 같은 헤더로 성공했습니다. 

PUT 요청만 401이 난다면, body 파싱과 관련된 문제일 수 있습니다. Hurl 테스트는 PUT 요청 시 JSON body를 보냅니다.
```hurl
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "bio": "Updated bio"
  }
}
HTTP 200
```
Fastify는 body가 있는 요청에 대해 Content-Type이 application/json이면 자동으로 body를 파싱합니다. PUT 핸들러에서 `request.body`를 읽기 전에 인증을 수행하는 로직은 이미 inline으로 변경했습니다. 그런데 PUT 핸들러에서 `const token = ...` 선언이 중복되었을 가능성이 있습니다. 이전 GET 핸들러 수정 때 `const token = jwt.sign(...)`을 `const newToken`으로 바꿨는데, PUT 핸들러에서는 `const token = (request.headers as any).authorization as string | undefined;`를 사용하고 있었습니다. 혹시 PUT 핸들러 맨 위에서의 `const token`이 GET 핸들러에서의 `const token = jwt.sign...`와 충돌? 아니요, 핸들러가 다르고 스코프가 다릅니다.

더 큰 문제는, PUT 핸들러가 전혀 등록되지 않았을 가능성입니다. `user.ts`에서 `export async function userRoutes(app: any): Promise<void> { ... }` 함수 안에 GET과 PUT이 모두 정의되어 있고, `server.ts`에서 `await app.register(userRoutes);`를 호출하므로 GET과 PUT 모두 등록되어야 합니다. 하지만 `userRoutes` 함수가 `any` 타입으로 선언되어 있고, `app.put(...)`을 호출할 때 `app`이 Fastify 인스턴스인지 TypeScript가 알 수 없어, 런타임에 문제가 생기기 어려워 보입니다.

잠깐. "로그에는 PUT 요청이 들어왔을 때 디버그 로그가 전혀 찍히지 않았습니다." -> 서버 로그를 다시 보면, PUT 요청에 대한 로그는
`{"level":30,"time":1785078196326,"pid":85875,"hostname":"Dohyunui-MacBookPro.local","reqId":"req-4","req":{"method":"PUT","url":"/api/user","host":"localhost:8000","remoteAddress":"127.0.0.1","remotePort":58651},"msg":"incoming request"}`
`{"level":30,"time":1785078196326,"pid":85875,"hostname":"Dohyunui-MacBookPro.local","reqId":"req-4","res":{"statusCode":401},"responseTime":0.479457999999795,"msg":"request completed"}`
이렇게 찍혀 있습니다. 같은 reqId "req-4"로 요청이 들어왔고 응답이 401로 나갔다고 Fastify 자체에서 로깅한 것입니다. 이건 Fastify의 기본 로거가 찍어준 것입니다. 제 디버그 로그(`[GET /api/user] ...`)가 안 찍혔다는 것은, `app.put("/api/user", ...)` 핸들러 내부의 코드가 전혀 실행되지 않았다는 뜻입니다. 

이는 Fastify에서 `app.put`이 아닌 다른 메서드에 등록되었거나, 라우트가 덮어씌워졌을 가능성을 시사합니다. `app.register(userRoutes)`가 호출될 때 `userRoutes`가 함수를 실행하여 `app.put`과 `app.get`을 등록합니다. 만약 `userRoutes` 함수에서 예외가 발생하여 함수가 중간에 종료되면, PUT 라우트 등록 전에 GET만 등록되고 종료될 수 있습니다. 하지만 GET은 성공했으므로, `userRoutes` 함수는 적어도 GET까지는 실행되었습니다. 

`app.get`과 `app.put`이 같은 핸들러 안에서 정의되지만, `app.get`이 비동기 함수이고, 그 안에서 예외가 발생했으면 `app.put` 등록 전에 함수가 종료되었을 수 있습니다. 하지만 GET 핸들러는 라우트 등록 코드가 아니라, 라우트가 호출되었을 때 실행되는 핸들러입니다. `app.get("/api/user", async ...)`는 라우트를 등록하는 코드이므로, 함수 호출 시점에 즉시 등록되어 완료됩니다. 비동기 핸들러라도 등록 시점에는 에러가 나지 않습니다. 

그렇다면 `userRoutes` 함수 내에서 `app.put` 라인이 실행되지 않을 이유가 무엇인가? `user.ts`의 코드 순서를 보면:
```typescript
export async function userRoutes(app: any): Promise<void> {
  // GET /api/user
  app.get("/api/user", async (request: AuthRequest, reply: FastifyReply) => { ... });

  // PUT /api/user
  app.put("/api/user", async (request: AuthRequest, reply: FastifyReply) => { ... });
}
```
명백히 두 줄이 모두 있습니다.

혹시 `app.put` 호출 시 `app`이 `any` 타입이라 TypeScript가 경고를 내지만, 실제로는 Fastify 인스턴스이므로 작동합니다.

그런데 `PUT 요청이 들어왔을 때 디버그 로그가 전혀 찍히지 않았다`는 것은, 요청이 `app.put("/api/user", ...)`에 등록된 핸들러로 라우팅되지 않았다는 뜻입니다. Fastify에서 동일한 메서드, 동일한 경로에 두 개의 핸들러가 등록되면 마지막 하나만 유효합니다. `articlesRoutes` 등에서 PUT `/api/user`를 등록하고 있지 않은지 확인해야 합니다. `articles.ts`를 보면 아티클 관련 라우트만 있으므로 `/api/user`와는 무관합니다.

정말 이상한 점은, GET은 성공했고 PUT은 401이며, PUT 핸들러 코드가 실행되지 않았다는 것입니다. PUT 요청 시 Fastify가 라우트를 찾지 못하면 404를 반환해야 합니다. 401을 반환했다면, 전역 preHandler가 실행되었거나, 다른 라우트가 매칭되어 401을 보낸 것입니다. 

`server.ts`를 보면 `await app.register(authPlugin);` 이후에 어떤 preHandler도 등록하지 않았습니다. `authPlugin` 내부를 다시 보겠습니다.
```typescript
export const authPlugin: FastifyPluginAsync = async (fastify) => {
  fastify.decorate("authenticate", authenticate);
};
```
이 플러그인은 `decorate`만 하고 `addHook`이나 `setGlobalPreHandler`를 호출하지 않습니다. 따라서 전역 preHandler는 없습니다.

그러면 왜 PUT 요청이 401을 받는가? 유일한 가능성은, PUT 요청이 실제로는 `/api/user`로 가지 않았다는 것입니다. Hurl 테스트 파일에서 PUT 요청의 URL이 `{{host}}/api/user`로 되어 있는지 다시 확인했습니다. `auth.hurl` 파일의 53번째 줄을 보면 맞습니다.

또 다른 가능성: PUT 요청의 Authorization 헤더가 GET 요청과 다르게 해석되어, 401을 보낸 곳이 PUT 핸들러가 아닌, 다른 미들웨어나 라우트일 수 있습니다. Hurl에서 `Authorization: Token {{token}}`으로 보내면 Fastify는 이를 `request.headers.authorization`에 문자열 `Token <token>`으로 받습니다. GET 핸들러에서는 `authHeader.match(/^Token\s+(.+)$/i)`로 정상 추출했습니다. PUT에서도 동일하게 추출해야 합니다.

그런데 PUT 핸들러에서 `const authHeader = (request.headers as any).authorization as string | undefined;`를 썼다면 동일한 방식으로 작동해야 합니다. 만약 PUT 핸들러가 아예 실행되지 않았다면, `app.put("/api/user", ...)` 등록 자체가 실패했을 가능성이 있습니다.

등록 실패 가능성: `user.ts`의 `app.put` 호출을 하며 `request: AuthRequest` 매개변수 타입에서 에러가 나서 `userRoutes` 함수 전체가 예외 종료? `AuthRequest`는 `FastifyRequest`를 확장한 인터페이스이므로 타입 에러가 나지 않아야 합니다. 하지만 strict 모드에서 `AuthRequest`와 `FastifyRequest` 사이의 호환성 문제가 있을 수 있습니다. 핸들러 함수 시그니처가 `FastifyRequestHandler` 타입과 맞지 않으면 런타임에 등록되지 않을 수 있습니다. Fastify v5에서는 핸들러 타입 체크가 엄격할 수 있습니다. 

`AuthRequest extends FastifyRequest`인데, 제네릭 매개변수로 `FastifyRequest<RawServerBase>` 등이 있을 수 있어, `AuthRequest`가 `FastifyRequest`의 서브타입이 아니라고 TypeScript가 판단할 수는 있으나, `any`로 캐스팅된 `app`의 `put` 메서드에 전달할 때는 런타임 체크가 없습니다.

결론: 로그를 더 자세히 봐야 합니다. `userRoutes` 함수 진입과 종료를 로깅하고, PUT 등록 시도 시 에러를 catch하여 로깅하겠습니다. 또는 간단히 `userRoutes` 전체를 try-catch로 감싸서 예외를 포착하겠습니다.
생각을 정리하면:
1. `GET /api/user`는 정상 작동 (로그 확인됨: decoded, request.user 할당, DB 조회, 응답 전송)
2. `PUT /api/user`는 401 반환, 그러나 PUT 핸들러 내부를 위한 디버그 로그(`[GET /api/user]`가 아닌 `[PUT /api/user]`)가 전혀 찍히지 않음.
3. PUT 핸들러가 실행되지 않았으므로, Fastify가 PUT 요청을 `/api/user`로 라우팅하지 않았거나, 라우팅은 했지만 핸들러가 아닌 다른 middleware/preHandler에서 401을 반환한 것임.
4. 전역 preHandler는 없음.
5. 따라서 PUT 요청이 실제 `/api/user`가 아닌 다른 URL로 갔거나, PUT 라우트가 등록되지 않았을 수 있음.
6. PUT 라우트가 등록되지 않은 이유: `userRoutes` 함수에서 `app.put` 호출 라인 이전에 예외가 발생하여 함수 실행이 중단됨. 유일하게 가능한 예외는 `app.get` 등록 시의 예외인데, `app.get` 등록은 동기이고, 핸들러는 비동기로 나중에 실행되므로 등록 시 예외가 날 이유가 거의 없음.
7. 그러나 `auth.hurl` 테스트에서 GET /api/user은 성공했습니다. 이는 GET 라우트가 등록되었고 핸들러도 정상 실행되었다는 뜻입니다. 따라서 `userRoutes` 함수는 최소한 GET 등록까지는 완료됨.
8. 그럼에도 401이 난다면, PUT 요청이 `userRoutes`의 PUT 핸들러가 아닌, 다른 곳에 등록된 PUT 핸들러로 갔다는 뜻이거나, PUT 핸들러가 실행되기 전에 `app.authenticate`나 다른 preHandler가 작동했다는 뜻입니다. `server.ts`에 `app.register(authPlugin)`를 했지만, 이 플러그인은 preHandler를 설정하지 않습니다.
9. PUT 요청이 실제로는 `/api/user`가 아니었다면, Hurl이 `Authorization: Token {{token}}` 헤더는 보내고 있지만, Content-Type이 누락되었거나 body 파싱 문제로 Fastify가 PUT 요청을 다른 방식으로 처리할 가능성은 없습니다.
10. User.ts PUT 핸들러 맨 윗줄에 `console.log("[PUT /api/user] called");`를 추가하고, 서버를 재기동하여 다시 테스트합니다. 만약 여전히 로그가 안 찍히면, PUT 라우트 등록 자체가 실패했음을 확신할 수 있습니다.
11. 또한 `server.ts`에서 `app.register(userRoutes)` 전에 `userRoutes`가 함수인지 확인하는 로그를 추가하는 방법도 있습니다. 하지만 `tsx`가 모듈 로딩을 하므로 `userRoutes`는 함수 참조로 전달될 것입니다.

PUT 핸들러 맨 위에 `console.log("[PUT /api/user] called");`를 작성하고, GET과 동일한 `try-catch` 구조로 감싸서 디버깅하겠습니다.
```

/edit src/routes/user.ts
* PUT /api/user 핸들러 맨 위에 console.log 추가 및 try-catch 적용
```

