      }
      const match = authHeader.match(/^Token\s+(.+)$/i);
      console.log("[PUT /api/user] match:", match ? "found" : "not found");
      if (!match) {
        console.log("[PUT /api/user] 401: no match");
        return reply.code(401).send({ errors: { token: ["is missing"] } });
      }
      let decoded: { id: string; username?: string; email?: string };
      try {
        decoded = jwt.verify(match[1], JWT_SECRET) as any;
        console.log("[PUT /api/user] decoded:", decoded);
      } catch (err) {
        console.error("[PUT /api/user] jwt.verify error:", err);
        return reply.code(401).send({ errors: { credentials: ["invalid"] } });
      }
      request.user = { id: decoded.id, username: decoded.username ?? "", email: decoded.email ?? "" };
      console.log("[PUT /api/user] request.user:", request.user);

      const userId = request.user!.id;
      console.log("[PUT /api/user] request.body:", request.body);

      const body = request.body as any;
      const updates: any = {};
      const { username, email, password, bio, image } = body.user ?? {};

      if (username !== undefined) updates.username = username;
      if (email !== undefined) updates.email = email;
      if (password !== undefined) updates.password = await bcrypt.hash(password, 10);
      if (bio !== undefined) updates.bio = normalize(bio);
      if (image !== undefined) updates.image = normalize(image);

      const user = await prisma.user.findUnique({ where: { id: userId } });
      if (!user) {
        return reply.code(404).send({ errors: [{ message: "User not found" }] });
      }

      const result = await prisma.user.update({
        where: { id: userId },
        data: updates,
        select: { id: true, username: true, email: true, bio: true, image: true },
      });

      const newToken = jwt.sign(
        { id: result.id, username: result.username, email: result.email },
        JWT_SECRET,
        { expiresIn: "30d" },
      );

      console.log("[PUT /api/user] sending 200 response");
      reply.send({
        user: {
          username: result.username,
          email: result.email,
          bio: result.bio ?? null,
          image: result.image ?? null,
          token: newToken,
        },
      });
    } catch (err) {
      console.error("[PUT /api/user] unexpected error:", err);
      return reply.code(500).send({ errors: { message: "internal server error" } });
    }
  });
}

