 ```
  // POST /api/articles/:slug/favorite
  app.post("/api/articles/:slug/favorite", async (request: any, reply) => {
    const token = extractToken(request);
    if (!token) {
      return reply.code(401).send({ errors: { token: ["is missing"] } });
    }
    const decoded = verifyToken(token);
    const slug = request.params.slug as string;

    const article = await prisma.article.findUnique({
      where: { slug },
      include: { author: { select: { id: true } } },
    });
    if (!article) {
      return reply.code(404).send({ errors: { article: ["not found"] } });
    }

    // 이미 즐겨찾기인지 확인
    const existing = await prisma.favorite.findUnique({
      where: {
        userId_articleId: {
          userId: decoded.id,
          articleId: article.id,
        },
      },
    });

    if (!existing) {
      await prisma.favorite.create({
        data: {
          userId: decoded.id,
          articleId: article.id,
        },
      });
    }

    // 응답 생성 (GET /api/articles/:slug와 동일하게 favorited, favoritesCount 포함)
    // ... (단일 아티클 조회 로직 재사용하여 응답 구성)
    // 간략하게 현재 사용자의 favorited 상태와 전체 favoritesCount만 다시 조회
    const favResult = await prisma.$queryRaw<{ userId: string }[]>`SELECT "userId" FROM "Favorite" WHERE "articleId" = ${article.id}`;
    const favoritesCount = favResult.length;
    const favorited = favResult.some((r) => r.userId === decoded.id);

    let tagList: string[] = [];
    let createdAt: any, updatedAt: any, body: string, description: string, title: string;
    if (article.tags) {
      tagList = article.tags.map((t: any) => t.name);
    }
    // article의 다른 필드들... article 객체에서 직접 가져올 수 있지만, prisma 응답 구조를 고려하여 매핑
    // 이미 article 객체에는 title, slug, description, body, createdAt, updatedAt, tags 등이 포함되어 있다고 가정.
    // 하지만 위 코드에서 article을 findUnique할 때 include를 author만 했으므로, title, body 등은 article 객체에 있음.
    reply.send({
      article: {
        title: article.title,
        slug: article.slug,
        description: article.description,
        body: article.body,
        tagList,
        createdAt: article.createdAt,
        updatedAt: article.updatedAt,
        favorited,
        favoritesCount,
        author: {
          username: article.author.username,
          bio: article.author.bio ?? null,
          image: article.author.image ?? null,
        },
      },
    });
  });
 ```
 위 코드에서 `article` 객체에 `author`가 포함되어 있지만, `select`로 `id`만 가져왔으므로 `article.author.username` 접근 시 undefined가 될 수 있음. `include` 시 `author: { select: { id: true, username: true, bio: true, image: true } }`로 수정해야 함.
 또한 `Favorite` 모델의 복합 ID명이 무엇인지 Prisma 스키마를 봐야 함. 스키마에 `@@id([userId, articleId])`만 있으므로, Prisma는 `userId_articleId`라는 이름을 자동 생성함. 따라서 `findUnique` 시 `where: { userId_articleId: { userId: ..., articleId: ... } }`가 맞음.

