 <read>src/routes/articles.ts</read> 235~250행.
 아, "이미 전체 Read한 파일"이라는 hook 알림이 있었지만, 정확한 old_string을 위해 다시 읽는 것이 불가피함. 이 경우, `Read` 도구의 `offset`과 `limit`을 사용하여 235~250행만 읽는 것은 허용되며, "직접 수정한 파일이라면 harness가 상태를 추적하므로 재읽기가 불필요"하다는 조언이지만, context 부족으로 인한 실수를 방지하기 위해 읽을 수 있음. 단, 가능하면 memory에 의존.
 이전 memory에서 242행이 `  });` (GET /api/articles 종료)였음. 244행이 `// GET /api/articles/:slug - 단일 아티클 조회`.
 이 정보를 바탕으로 old_string을 구성.
 old_string: `  });\n\n  // GET /api/articles/:slug - 단일 아티클 조회`
 new_string: `  });\n\n  // GET /api/articles/feed - 팔로우하는 사용자의 아티클 피드\n  app.get("/api/articles/feed", async (request: any, reply) => {\n    const token = extractToken(request);\n    if (!token) {\n      return reply.code(401).send({ errors: { token: ["is missing"] } });\n    }\n\n    const decoded = verifyToken(token);\n    const limit = Math.min(parseInt(request.query?.limit as string ?? "20", 10), 100);\n    const offset = parseInt(request.query?.offset as string ?? "0", 10);\n\n    // 현재 사용자가 팔로우하는 사용자 ID 목록 조회\n    const follows = await prisma.follow.findMany({\n      where: { followerId: decoded.id },\n      select: { followingId: true },\n    });\n    const followingIds = follows.map((f: any) => f.followingId);\n\n    if (followingIds.length === 0) {\n      return reply.send({ articles: [], articlesCount: 0 });\n    }\n\n    let where: any = { authorId: { in: followingIds } };\n\n    // tag 필터\n    const tagFilter = request.query?.tag as string | undefined;\n    if (tagFilter) {\n      const tag = await prisma.tag.findUnique({ where: { name: tagFilter } });\n      if (!tag) {\n        return reply.send({ articles: [], articlesCount: 0 });\n      }\n      where.tags = { some: { id: tag.id } };\n    }\n\n    // favorited 필터\n    const favoritedFilter = request.query?.favorited as string | undefined;\n    if (favoritedFilter) {\n      const favUser = await prisma.user.findUnique({ where: { username: favoritedFilter } });\n      if (!favUser) {\n        return reply.send({ articles: [], articlesCount: 0 });\n      }\n      const favArticleIds = await prisma.$queryRaw<string[]>`SELECT "articleId" FROM "Favorite" WHERE "userId" = ${favUser.id}`;\n      if (favArticleIds.length === 0) {\n        return reply.send({ articles: [], articlesCount: 0 });\n      }\n      where.id = { in: favArticleIds };\n    }\n\n    // author 필터\n    const authorFilter = request.query?.author as string | undefined;\n    if (authorFilter) {\n      const author = await prisma.user.findUnique({ where: { username: authorFilter } });\n      if (!author) {\n        return reply.send({ articles: [], articlesCount: 0 });\n      }\n      where.authorId = author.id;\n    }\n\n    const total = await prisma.article.count({ where });\n    const articles = await prisma.article.findMany({\n      where,\n      include: {\n        author: {\n          select: { id: true, username: true, bio: true, image: true },\n        },\n        tags: { select: { name: true } },\n      },\n      orderBy: { createdAt: "desc" },\n      take: limit,\n      skip: offset,\n    });\n\n    let currentUserId: string | null = decoded.id;\n    let favoritedMap: Record<string, boolean> = {};\n    let favCountMap: Record<string, number> = {};\n    if (articles.length > 0) {\n      const articleIds = articles.map((a: any) => a.id);\n      const favResults = await prisma.$queryRaw<{ articleId: string; userId: string }[]>`SELECT "articleId", "userId" FROM "Favorite" WHERE "articleId" IN (${articleIds})`;\n      for (const row of favResults) {\n        if (!favCountMap[row.articleId]) favCountMap[row.articleId] = 0;\n        favCountMap[row.articleId]++;\n        if (row.userId === currentUserId) {\n          favoritedMap[row.articleId] = true;\n        }\n      }\n    }\n\n    const result = articles.map((a: any) => ({\n      title: a.title,\n      slug: a.slug,\n      description: a.description,\n      tagList: (a.tags as Array<{ name: string }>).map((t) => t.name),\n      createdAt: a.createdAt,\n      updatedAt: a.updatedAt,\n      favorited: favoritedMap[a.id] ?? false,\n      favoritesCount: favCountMap[a.id] ?? 0,\n      author: {\n        username: a.author.username,\n        bio: a.author.bio ?? null,\n        image: a.author.image ?? null,\n      },\n    }));\n\n    reply.send({\n      articles: result,\n      articlesCount: total,\n    });\n  });\n\n  // POST /api/articles/:slug/favorite\n  app.post("/api/articles/:slug/favorite", async (request: any, reply) => {\n    const token = extractToken(request);\n    if (!token) {\n      return reply.code(401).send({ errors: { token: ["is missing"] } });\n    }\n    const decoded = verifyToken(token);\n    const slug = request.params.slug as string;\n\n    const article = await prisma.article.findUnique({\n      where: { slug },\n      include: { author: { select: { id: true, username: true, bio: true, image: true } } },\n    });\n    if (!article) {\n      return reply.code(404).send({ errors: { article: ["not found"] } });\n    }\n\n    const existing = await prisma.favorite.findUnique({\n      where: {\n        userId_articleId: {\n          userId: decoded.id,\n          articleId: article.id,\n        },\n      },\n    });\n\n    if (!existing) {\n      await prisma.favorite.create({\n        data: {\n          userId: decoded.id,\n          articleId: article.id,\n        },\n      });\n    }\n\n    const favResult = await prisma.$queryRaw<{ userId: string }[]>`SELECT "userId" FROM "Favorite" WHERE "articleId" = ${article.id}`;\n    const favoritesCount = favResult.length;\n    const favorited = favResult.some((r) => r.userId === decoded.id);\n\n    let tagList: string[] = [];\n    if (article.tags) {\n      tagList = article.tags.map((t: any) => t.name);\n    }\n\n    reply.send({\n      article: {\n        title: article.title,\n        slug: article.slug,\n        description: article.description,\n        body: article.body,\n        tagList,\n        createdAt: article.createdAt,\n        updatedAt: article.updatedAt,\n        favorited,\n        favoritesCount,\n        author: {\n          username: article.author.username,\n          bio: article.author.bio ?? null,\n          image: article.author.image ?? null,\n        },\n      },\n    });\n  });\n\n  // DELETE /api/articles/:slug/favorite\n  app.delete("/api/articles/:slug/favorite", async (request: any, reply) => {\n    const token = extractToken(request);\n    if (!token) {\n      return reply.code(401).send({ errors: { token: ["is missing"] } });\n    }\n    const decoded = verifyToken(token);\n    const slug = request.params.slug as string;\n\n    const article = await prisma.article.findUnique({\n      where: { slug },\n      include: { author: { select: { id: true, username: true, bio: true, image: true } } },\n    });\n    if (!article) {\n      return reply.code(404).send({ errors: { article: ["not found"] } });\n    }\n\n    await prisma.favorite.deleteMany({\n      where: {\n        userId: decoded.id,\n        articleId: article.id,\n      },\n    });\n\n    const favResult = await prisma.$queryRaw<{ userId: string }[]>`SELECT "userId" FROM "Favorite" WHERE "articleId" = ${article.id}`;\n    const favoritesCount = favResult.length;\n\n    let tagList: string[] = [];\n    if (article.tags) {\n      tagList = article.tags.map((t: any) => t.name);\n    }\n\n    reply.send({\n      article: {\n        title: article.title,\n        slug: article.slug,\n        description: article.description,\n        body: article.body,\n        tagList,\n        createdAt: article.createdAt,\n        updatedAt: article.updatedAt,\n        favorited: false,\n        favoritesCount,\n        author: {\n          username: article.author.username,\n          bio: article.author.bio ?? null,\n          image: article.author.image ?? null,\n        },\n      },\n    });\n  });\n\n  // GET /api/tags\n  app.get("/api/tags", async (request: any, reply) => {\n    const tags = await prisma.tag.findMany({\n      select: { name: true },\n      orderBy: { name: "asc" },\n    });\n    reply.send({\n      tags: tags.map((t) => t.name),\n    });\n  });\n\n  // GET /api/articles/:slug - 단일 아티클 조회`
